#!/usr/bin/env python3
"""Turn 35 Wave 86: THE STADIUM BUILD-ORDER RULE, AND THE TRAINING FACILITY'S REAL LADDER.

Wave 86's centrepieces:

1. THE STADIUM BUILD-ORDER RULE, which the corpus did not have and which changes how the
   stadium is actually built: **build each stand directly to its optimal level in one go**,
   because "if you build a side only partially, the next time you will have to pay the full
   price to complete it." Plus the named optimal build - North 20, North East 49, East 26,
   South East 45, South 20, South West 49, West 26, North West 49 - which reaches the 52-coin
   maximum for a little over 10,000 coins, and the instruction that **roofs are costly optics
   you do not need**.

2. THE TRAINING FACILITY'S REAL LADDER: each level unlocks a *group* of formations, and the
   gem discount is 5% / 10% / 15% at levels 1 / 2 / 3. That converts the corpus's "Training
   is the priority facility" into a priced decision: **stay at level 1 if you are maxing with
   coins, and only reach level 5 if you are maxing with gems.**

3. A CONFLICT ON THE DISCOUNT LADDER. The corpus carries a six-level 0/5/10/15/20/30%
   discount ladder, which contradicts the twice-confirmed five-level 75 x N price ladder and
   the 5/10/15% level-by-level figures from this wave's source. Recorded, not resolved.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w86')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_fc=new_ev("r/DreamLeagueSoccer 1b2xxys 'TRAINING FACILITY GUIDE' (29 Feb 2024 - the per-level gem discount, the formation-group unlocks, the priced guidance on which level to stop at, and the 75/150/225/300/375 price ladder), r/DreamLeagueSoccer zfrglq 'Cost of facilities in DLS 23' (8 Dec 2022 - the 1125-gem total per facility, the named optimal stadium build, the no-roofs instruction and the partial-build penalty), r/DreamLeagueSoccer 1q860kk (9 Jan 2026 - the minority facility-gem position: only Accommodation and Training are worth gems), r/DreamLeagueSoccer 1h6nprr (4 Dec 2024 - the Accommodation cost ladder 75 through 750 = 4,125), r/DreamLeagueSoccer 1b183rw '3 Months of Dream League Soccer' (the benchmark dataset, already in the corpus), gtrmod.com (23 Jun 2026 - the Fanzone at level 5, a mod site), dlsgame.net/index-player-dls-26 (8 Dec 2025 - a full DLS26 player rating index), dream-league-soccer.fandom.com/wiki/Classic_Players (a second corrupted fandom page), z2u.com DLS26 best players (8 Jun 2026 - a marketplace table putting Yamal at 86), dreamkitsapp.com/data (Desailly 85 as a Classic), a retry of the LIVE rank-names search with 'soccer' in the query, per the wave-85 contamination rule",
    "THE STADIUM BUILD-ORDER RULE, THE TRAINING FACILITY'S REAL LADDER, AND A CONFLICT ON THE DISCOUNT. (1) THE STADIUM BUILD-ORDER RULE, new to the corpus and it changes how the stadium is built: '**If you cannot afford to build it at once, build each time one (or more) of the 8 side directly to its optimal level (eg North directly to 20). This costs between 900-1300 coins. If you build a side only partially, the next time you will have to pay the full price to complete it.**' So a partial stand is a trap - it must be finished in one purchase or you pay twice. (2) THE NAMED OPTIMAL STADIUM BUILD, reaching the 52-coin maximum at minimum cost: '**North 20, North East 49, East 26, South East 45, South 20, South West 49, West 26, North West 49.** It brings the max reward of 52 coins per home match at minimum cost (slightly more than 10000 coins). **No need to have roofs, it's only costly optics.**' That is a concrete build order for the corpus's capacity gate, and it prices the whole thing at a little over 10,000 coins - which is the same order as the 15,000-coin Division 3 gate. (3) THE TRAINING FACILITY'S REAL LADDER: 'LEVEL 1: This gives a **5% discount off gems** and gives you **a group of formations** you can choose from, this is also a great level to stay at if you're deciding to **use coins and coaches** to max players instead of gems' - 'LEVEL 2: this gives a **10% off discount** off gems, and gives you **another group of formations**' - 'LEVEL 3: this gives a **15% off discount** similar to level 2... This is ideal for formations and play style benefits, not much of a difference from gems between 10% and 15%' - 'LEVEL 5: to get to this position you will have to spend around 1175 gems... You will now have **every group of formations in the game**, and also have the **cheapest coaches** as well, this is only ideal if you plan on maxing your team with only gems.' So formations unlock in GROUPS, one group per Training level, and level 5 completes the set. (4) THE PRICED GUIDANCE that converts the corpus's 'Training is the priority facility' into a decision: **stay at level 1 if you are maxing with coins; reach level 5 only if you are maxing with gems.** The corpus's F2P cost of a max (~32,000 coins) is exactly the case where level 1 is enough. (5) A CONFLICT ON THE DISCOUNT LADDER: the corpus carries CLAIM-177, 'Recruitment/Training facility discount tiers confirmed for coaching costs: 0% / 5% / 10% / 15% / 20% / 30% (six levels)'. That contradicts the twice-confirmed five-level 75 x N price ladder (75/150/225/300/375 = 1,125 per facility) and this wave's level-by-level 5/10/15% figures. Six levels cannot coexist with a five-level price ladder. Recorded, not resolved - the level attribution in this wave's source is the more specific and matches the price ladder. (6) A MINORITY FACILITY POSITION: 'If you want to use them on facilities, **the only facilities worth your gems are the Accommodation and Training facilities**. You should only use your gems for coaches if your Training facility is maxed out. Also, don't use your gems to max out your regular players, **buy 80 OVR defenders for coaches**, gems are better used for maxing classic players when you get them.' That is a narrower gem rule than the corpus's six-facility priority order, and it is a real disagreement worth holding as a minority position. (7) THE RANK-NAMES RETRY: the search was re-run with 'soccer' in the query, per the wave-85 contamination rule. It still returned nothing above Veteran - so the gap is confirmed source-limited rather than query-limited. (8) A SECOND CORRUPTED FANDOM PAGE: dream-league-soccer.fandom.com/wiki/Classic_Players lists Lev Yashin at '0 Overall' and Paolo Maldini and Franz Beckenbauer at '100 Overall', both impossible against the confirmed 86 ceiling. The wiki's Classic Players page joins its Coins page as rejected for figures. (9) A NEW PLAYER-RATING INDEX: dlsgame.net publishes a full DLS26 player index with ratings and positions - Kvaratskhelia 84 LW, Saliba 84 CB, Bruno Fernandes 84 CM, Vitinha 84 CM, Bastoni 84 CB, Saka 84 RW, Julian Alvarez 84 CF, Alisson 84 GK, Declan Rice 84 CM, Lewandowski 84 CF - down through the 79s. A usable recruitment resource alongside sakibpro and dreamkitsapp. (10) A MINOR RATING CONFLICT: z2u.com puts Lamine Yamal at 86, where every other source has him at 85. z2u is a marketplace site; the 85 stands. (11) Marcel Desailly is confirmed as a Classic at 85 CB, consistent with the Italian League Classics on the current Prize Ladder.",
    "THE STADIUM BUILD-ORDER RULE: build each stand directly to its optimal level in one purchase, because a partial stand costs full price to complete - and roofs are costly optics you do not need. THE NAMED OPTIMAL BUILD: North 20, North East 49, East 26, South East 45, South 20, South West 49, West 26, North West 49 - the 52-coin maximum for a little over 10,000 coins. THE TRAINING FACILITY'S REAL LADDER: each level unlocks a GROUP of formations, and the gem discount is 5% / 10% / 15% at levels 1 / 2 / 3, with level 5 completing every formation group and giving the cheapest coaches. THE PRICED GUIDANCE: stay at level 1 if maxing with coins, reach level 5 only if maxing with gems. A CONFLICT on the discount ladder - the corpus's six-level 0/5/10/15/20/30% figure cannot coexist with the confirmed five-level price ladder. A MINORITY FACILITY POSITION: only Accommodation and Training are worth gems, and buy 80 OVR defenders for coaches. THE RANK-NAMES RETRY with 'soccer' in the query still found nothing above Veteran, so that gap is source-limited. A SECOND CORRUPTED FANDOM PAGE. A NEW PLAYER-RATING INDEX",
    "THE STADIUM BUILD-ORDER RULE AND THE TRAINING FACILITY'S REAL LADDER",
    quality="community")

add_claim("THE STADIUM BUILD-ORDER RULE, new to the corpus: '**If you cannot afford to build it at once, build each time one (or more) of the 8 side directly to its optimal level (eg North directly to 20). This costs between 900-1300 coins. If you build a side only partially, the next time you will have to pay the full price to complete it.**' So a partially built stand is a trap - it must be finished in one purchase or you pay twice.", 2, "stadium/build-order-partial-stand-penalty", [e_fc], notes="Changes how the stadium is actually built; a silent coin sink avoided")
add_claim("THE NAMED OPTIMAL STADIUM BUILD, reaching the 52-coin maximum at minimum cost: **North 20 · North East 49 · East 26 · South East 45 · South 20 · South West 49 · West 26 · North West 49** - 'It brings the max reward of 52 coins per home match at minimum cost (slightly more than 10000 coins).' **No roofs needed - 'it's only costly optics.'**", 2, "stadium/named-optimal-build", [e_fc], notes="A concrete build order for the capacity gate, priced at a little over 10,000 coins")
add_claim("THE TRAINING FACILITY'S PER-LEVEL GEM DISCOUNT: **level 1 = 5% off gems, level 2 = 10%, level 3 = 15%** - and 'not much of a difference from gems between 10% and 15%', so the discount curve flattens after level 2. Level 5 gives 'the cheapest coaches as well'.", 2, "facilities/training-discount-ladder", [e_fc])
add_claim("THE TRAINING FACILITY UNLOCKS FORMATIONS IN GROUPS: 'LEVEL 1... gives you **a group of formations** you can choose from' - 'LEVEL 2... gives you **another group of formations**' - 'LEVEL 5: You will now have **every group of formations in the game**.' So the formation catalogue is gated one group per Training level, which is a second reason the facility outranks the others early.", 2, "facilities/training-formation-groups", [e_fc], notes="Extends the corpus's 'formations come from the Training Centre' into a per-level structure")
add_claim("THE PRICED TRAINING DECISION, which converts the corpus's 'Training is the priority facility' into a rule: '**this is also a great level to stay at if you're deciding to use coins and coaches to max players instead of gems**' and level 5 'is only ideal if you plan on maxing your team with only gems.' **So stay at level 1 if you are maxing with coins - which is the F2P case - and reach level 5 only if you are maxing with gems.**", 2, "facilities/training-priced-decision", [e_fc], notes="Directly actionable: the F2P route needs Training L1, not L5")
add_claim("CONFLICT ON THE DISCOUNT LADDER: the corpus carries CLAIM-177 - 'Recruitment/Training facility discount tiers confirmed for coaching costs: 0% / 5% / 10% / 15% / 20% / 30% (**six levels**).' That cannot coexist with the twice-confirmed five-level 75 x N price ladder (75/150/225/300/375 = 1,125 per facility) or with this wave's level-by-level 5/10/15% figures. **Recorded, not resolved** - the level attribution here is the more specific and matches the price ladder, so the six-level/30% figure is the suspect one.", 3, "errata/training-discount-ladder-conflict", [e_fc], notes="Version attribution is the likely cause; the price ladder is the anchor")
add_claim("A MINORITY FACILITY POSITION worth holding: 'the **only facilities worth your gems are the Accommodation and Training facilities**. You should only use your gems for coaches if your Training facility is maxed out. Also, don't use your gems to max out your regular players, **buy 80 OVR defenders for coaches**, gems are better used for maxing classic players when you get them.' A narrower gem rule than the corpus's six-facility priority order - a real disagreement, not an error.", 3, "facilities/minority-position-accommodation-and-training-only", [e_fc], notes="Held as a minority position against the six-facility order")
add_claim("THE RANK-NAMES RETRY: the search for LIVE rank names above Veteran was re-run with 'soccer' in the query, per the wave-85 contamination rule. **It still returned nothing above Veteran** - so the gap is confirmed source-limited rather than query-limited, and the only remaining route is a device read.", 3, "dll/rank-names-retry-negative", [e_fc], notes="Closes the 'maybe it was the query' possibility")
add_claim("A SECOND CORRUPTED FANDOM PAGE: dream-league-soccer.fandom.com/wiki/Classic_Players lists Lev Yashin at '**0 Overall**' and Paolo Maldini and Franz Beckenbauer at '**100 Overall**' - both impossible against the confirmed 86 rating ceiling. The wiki's Classic Players page joins its Coins page as rejected for figures; the wiki's Stadium page remains usable for structure only.", 4, "errata/fandom-classic-players-page-corrupted", [e_fc], notes="Second fandom-page rejection")
add_claim("A NEW PLAYER-RATING INDEX: dlsgame.net publishes a full DLS26 player index with ratings and positions - Kvaratskhelia 84 LW, Saliba 84 CB, Bruno Fernandes 84 CM, Vitinha 84 CM, Bastoni 84 CB, Saka 84 RW, Julian Alvarez 84 CF, Alisson 84 GK, Declan Rice 84 CM, Lewandowski 84 CF, Lautaro Martinez 84 CF, running down through the 79s. A usable recruitment resource alongside sakibpro and dreamkitsapp.", 3, "transfers/dlsgame-player-index", [e_fc])
add_claim("A MINOR RATING CONFLICT: z2u.com puts Lamine Yamal at **86**, where every other source has him at 85. z2u is a marketplace site with no editorial standing; the 85 stands, consistent with the corpus's 86 ceiling held by Dembélé, Mbappé, Kane and Haaland.", 4, "errata/yamal-86-outlier", [e_fc])
add_claim("Marcel Desailly is confirmed as a **Classic at 85 CB**, consistent with the Italian League Classics on the current Prize Ladder - and Desailly was named in the corpus's Classics list from the Prize Ladder's named roster.", 3, "cards/desailly-classic-85", [e_fc])

for p in ['EV-499_stadium_build_order.html','EV-499b_training_ladder.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
